// AdminAlertDetail FraudAlert plus audit entries whose action text mentions the alert code (case history).
type AdminAlertDetail struct {
	Audit []AuditEntry `json:"audit"`
	Code  string       `json:"code"`

	// Confidence Engine confidence 0-1.
	Confidence float64   `json:"confidence"`
	DetectedAt time.Time `json:"detectedAt"`
	Evidence   []string  `json:"evidence"`

	// Graph Relation graph for network-type alerts.
	Graph *struct {
		Edges []struct {
			Label  *string `json:"label,omitempty"`
			Source string  `json:"source"`
			Target string  `json:"target"`
		} `json:"edges"`
		Nodes []struct {
			Flagged *bool                          `json:"flagged,omitempty"`
			Id      string                         `json:"id"`
			Kind    AdminAlertDetailGraphNodesKind `json:"kind"`
			Label   string                         `json:"label"`
		} `json:"nodes"`
	} `json:"graph,omitempty"`
	Id            string `json:"id"`
	Investigation *struct {
		By    string `json:"by"`
		Notes []struct {
			At   time.Time `json:"at"`
			By   string    `json:"by"`
			Text string    `json:"text"`
		} `json:"notes"`
		OpenedAt time.Time `json:"openedAt"`
	} `json:"investigation,omitempty"`
	Resolution *struct {
		At      time.Time `json:"at"`
		By      string    `json:"by"`
		Outcome string    `json:"outcome"`
		Reason  string    `json:"reason"`
	} `json:"resolution,omitempty"`

	// Score Risk score 0-100.
	Score float64 `json:"score"`

	// Source 'system' = engine recommendation; 'manual' = case opened by an admin.
	Source   AdminAlertDetailSource `json:"source"`
	Status   AlertStatus            `json:"status"`
	Subjects []Subject              `json:"subjects"`
	Title    string                 `json:"title"`
	Type     AlertType              `json:"type"`
}

